mapper.select:
SELECT t1.COM_TYPE AS comType , t1.INFO_TYPE AS infoType , t1.SHRN_ISCD AS shrnIscd , t1.STND_ISCD AS stndIscd , t1.KOR_NAME AS korName , t1.ATM_CLS_CODE AS atmClsCode , t1.ACPR AS acpr , t1.MMSC_CLS_CODE AS mmscClsCode , t1.PROD_NO AS prodNo , t1.PROD_NAME AS prodName , CASE t1.COM_TYPE WHEN '1' THEN '금리' WHEN '2' THEN '통화' WHEN '3' THEN '상품' ELSE t1.COM_TYPE END AS comTypeName , CASE t1.INFO_TYPE WHEN '1' THEN '선물' WHEN '2' THEN 'SP선물' WHEN '5' THEN '콜옵션' WHEN '6' THEN '풋옵션' ELSE t1.INFO_TYPE END AS infoTypeName , CASE t1.ATM_CLS_CODE WHEN '1' THEN 'ATM' WHEN '2' THEN 'ITM' WHEN '3' THEN 'OTM' ELSE t1.ATM_CLS_CODE END AS atmClsName , CASE t1.MMSC_CLS_CODE WHEN '0' THEN '연결선물' WHEN '1' THEN '최근월물' WHEN '2' THEN '차근월물' WHEN '3' THEN '차차근월물' WHEN '4' THEN '차차차근월물' ELSE t1.MMSC_CLS_CODE END AS mmscClsName FROM FO_COM_CODE t1 WHERE 1 = 1
AND t1.COM_TYPE = #{comType}
AND t1.INFO_TYPE = #{infoType}
ORDER BY t1.COM_TYPE ASC, t1.INFO_TYPE ASC, t1.STND_ISCD ASC

SELECT COUNT(1)
  FROM FO_COM_CODE
 WHERE COM_TYPE  = #{comType}
   AND INFO_TYPE = #{infoType}
   AND STND_ISCD = #{stndIscd}

mapper.update:
UPDATE FO_COM_CODE
   SET SHRN_ISCD     = #{shrnIscd, jdbcType=VARCHAR},
       KOR_NAME      = #{korName, jdbcType=VARCHAR},
       ATM_CLS_CODE  = #{atmClsCode, jdbcType=VARCHAR},
       ACPR          = #{acpr, jdbcType=NUMERIC},
       MMSC_CLS_CODE = #{mmscClsCode, jdbcType=VARCHAR},
       PROD_NO       = #{prodNo, jdbcType=VARCHAR},
       PROD_NAME     = #{prodName, jdbcType=VARCHAR}
 WHERE COM_TYPE      = #{comType}
   AND INFO_TYPE     = #{infoType}
   AND STND_ISCD     = #{stndIscd}

mapper.delete:
DELETE FROM FO_COM_CODE
 WHERE COM_TYPE  = #{comType}
   AND INFO_TYPE = #{infoType}
   AND STND_ISCD = #{stndIscd}
